#include "../../inc/config/ServerConfig.hpp"
#include <algorithm>

ServerConfig::ServerConfig()
	: _host("0.0.0.0")
	, _port(80)
	, _root("./www")
	, _index("index.html")
	, _maxBodySize(1048576)  // 1MB default
	, _autoindex(false)
{
}

ServerConfig::ServerConfig(const ServerConfig& other)
	: _host(other._host)
	, _port(other._port)
	, _serverNames(other._serverNames)
	, _root(other._root)
	, _index(other._index)
	, _maxBodySize(other._maxBodySize)
	, _errorPages(other._errorPages)
	, _locations(other._locations)
	, _autoindex(other._autoindex)
{
}

ServerConfig& ServerConfig::operator=(const ServerConfig& other) {
	if (this != &other) {
		_host = other._host;
		_port = other._port;
		_serverNames = other._serverNames;
		_root = other._root;
		_index = other._index;
		_maxBodySize = other._maxBodySize;
		_errorPages = other._errorPages;
		_locations = other._locations;
		_autoindex = other._autoindex;
	}
	return *this;
}

ServerConfig::~ServerConfig() {
}

// ============================================================================
// Getters
// ============================================================================

const std::string& ServerConfig::getHost() const {
	return _host;
}

int ServerConfig::getPort() const {
	return _port;
}

const std::vector<std::string>& ServerConfig::getServerNames() const {
	return _serverNames;
}

const std::string& ServerConfig::getRoot() const {
	return _root;
}

const std::string& ServerConfig::getIndex() const {
	return _index;
}

size_t ServerConfig::getMaxBodySize() const {
	return _maxBodySize;
}

const std::map<int, std::string>& ServerConfig::getErrorPages() const {
	return _errorPages;
}

const std::vector<LocationConfig>& ServerConfig::getLocations() const {
	return _locations;
}

bool ServerConfig::getAutoindex() const {
	return _autoindex;
}

// ============================================================================
// Setters
// ============================================================================

void ServerConfig::setHost(const std::string& host) {
	_host = host;
}

void ServerConfig::setPort(int port) {
	_port = port;
}

void ServerConfig::addServerName(const std::string& name) {
	_serverNames.push_back(name);
}

void ServerConfig::setRoot(const std::string& root) {
	_root = root;
}

void ServerConfig::setIndex(const std::string& index) {
	_index = index;
}

void ServerConfig::setMaxBodySize(size_t size) {
	_maxBodySize = size;
}

void ServerConfig::addErrorPage(int code, const std::string& path) {
	_errorPages[code] = path;
}

void ServerConfig::addLocation(const LocationConfig& location) {
	_locations.push_back(location);
}

void ServerConfig::setAutoindex(bool autoindex) {
	_autoindex = autoindex;
}

// ============================================================================
// Methods
// ============================================================================

std::string ServerConfig::getErrorPage(int code) const {
	std::map<int, std::string>::const_iterator it = _errorPages.find(code);
	if (it != _errorPages.end())
		return it->second;
	return "";
}

const LocationConfig* ServerConfig::findLocation(const std::string& uri) const {
	const LocationConfig* bestMatch = NULL;
	size_t bestMatchLength = 0;

	for (size_t i = 0; i < _locations.size(); ++i) {
		const std::string& locationPath = _locations[i].getPath();

		// Check if the URI starts with the location path
		if (uri.compare(0, locationPath.length(), locationPath) == 0) {
			// If exact match or location path ends with / or URI continues with /
			if (uri.length() == locationPath.length() ||
				locationPath[locationPath.length() - 1] == '/' ||
				uri[locationPath.length()] == '/' ||
				locationPath == "/") {

				if (locationPath.length() > bestMatchLength) {
					bestMatchLength = locationPath.length();
					bestMatch = &_locations[i];
				}
			}
		}
	}

	return bestMatch;
}

bool ServerConfig::matchServerName(const std::string& host) const {
	// Extract hostname without port
	std::string hostname = host;
	size_t colonPos = hostname.find(':');
	if (colonPos != std::string::npos)
		hostname = hostname.substr(0, colonPos);

	// Check against server names
	for (size_t i = 0; i < _serverNames.size(); ++i) {
		if (_serverNames[i] == hostname)
			return true;
	}

	// If no server names defined, match any
	return _serverNames.empty();
}

void ServerConfig::clear() {
	_host = "0.0.0.0";
	_port = 80;
	_serverNames.clear();
	_root = "./www";
	_index = "index.html";
	_maxBodySize = 1048576;
	_errorPages.clear();
	_locations.clear();
	_autoindex = false;
}

bool ServerConfig::isValid() const {
	if (_port < 1 || _port > 65535)
		return false;
	if (_root.empty())
		return false;
	return true;
}
